#!/usr/bin/env python
# ── GENERATED by matsci-kb-kit build/build_kit.py — DO NOT EDIT (真源见 kit.yaml) ──
r"""任务 B 执行器：按 decisions JSON 对 L1 页做「补一手源」或「如实降级」。

为什么要有这个工具
------------------
`evidence_base: single-source / secondhand` 有 69 个页。逐页手改 69 个文件既慢又容易写错数字；
但**数字不能由脚本猜**——所以这里的分工是：

  · **判断**（哪一页该补源、哪一页如实降级）由人/模型在 decisions JSON 里给出；工具不判断。
  · **数字**（一手源几篇、二手占比多少、卡名是什么）由工具**现场用
    `qc_evidence_base.classify()` 同一套口径重算**，不抄旧结论、不手打。
  · **写盘**只做两件事：往 `sources:` 追加**已存在**的 source 卡；或在
    `## 证据状态与判据` 段首插一行 `> 证据强度：…` 的限定语。不动正文论证。

decisions JSON（列表）：
    [{"page": "wiki/concepts/MXene.md", "action": "downgrade", "reason": "库内仅 1 篇一手源"},
     {"page": "wiki/concepts/某页.md", "action": "upgrade",
      "add": ["sources/2025-xxx"], "reason": "正文已以该卡为主要证据"}]

红线
----
· `upgrade` 只接受**库内已存在**的 source 卡名；不建卡、不猜 DOI（CLAUDE.md：禁止凭标题猜内容建卡）。
· `downgrade` 的注记文字由工具生成，**页内已有同一条**则跳过（幂等）。
· 默认干跑；`--apply` 才落盘；写前备份 `.qc_backup_YYYYMMDD/`，写后复算（能读回 + frontmatter 仍解析 + 注记/条目确实在）。
· 换行走 `kb_lib.write_text_verified`（按多数票保留）。

用法
----
    python tools/qc_evidence_note.py --plan decisions.json            # 干跑，打印每页将写什么
    python tools/qc_evidence_note.py --plan decisions.json --apply
    python tools/qc_evidence_note.py --selftest
    python tools/qc_evidence_note.py --derive > plan_all_downgrade.json  # 生成「全部降级」骨架
"""
import os
import re
import sys
import json
import glob
import shutil
import datetime

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
os.chdir(ROOT)
sys.path.insert(0, "tools")
from kb_lib import (read_text, split_frontmatter, parse_frontmatter,  # noqa: E402
                    join_frontmatter, write_text_verified, console_encoding,
                    extract_outlinks)
import qc_evidence_base as QE                                          # noqa: E402

console_encoding()

EV_HEADING = "## 证据状态与判据"
SEE_HEADINGS = ("## 参见", "## 参考")
NOTE_HEAD = "> 证据强度："
NOTE_TAIL = "，不得作为领域共识引用。"


# ---------------------------------------------------------------- 证据画像
def profile(page, src_pages):
    """用与 qc_evidence_base **同一套口径**重算：→ dict(value, why, prim[], second[], pre[], total, body_extra[])"""
    _fm, hits = QE.evidence_for(page, src_pages)
    value, why = QE.classify(hits)
    prim, second, pre = [], [], []
    names = []
    text = read_text(page)
    a, b = split_frontmatter(text)
    fm = parse_frontmatter(a)
    srcs = fm.get("sources") or []
    if isinstance(srcs, str):
        srcs = [srcs]
    for s in srcs:
        nm = QE._resolve_source_name(s)
        if nm not in src_pages:
            continue
        names.append(nm)
        sr = str(src_pages[nm][0].get("source_reliability") or "")
        # 判定顺序必须与 classify() 一致：二手 → 同行评审 → 预印本
        if QE.SECONDHAND_PAT.search(sr):
            second.append(nm)
        elif QE._peer_hits(sr):
            prim.append(nm)
        elif QE.PREPRINT_PAT.search(sr):
            pre.append(nm)
    # 正文引用了、但 `sources:` 未登记的 source 卡（= 元数据登记不全的客观证据）
    body_cards = set()
    for ln in extract_outlinks(b):
        tgt = ln.replace("\\|", "|").split("|")[0].split("#")[0].strip().replace("\\", "")
        nm = tgt.split("/")[-1]
        if nm.endswith(".md"):
            nm = nm[:-3]
        if nm in src_pages:
            body_cards.add(nm)
    extra = sorted(body_cards - set(names))
    return {"value": value, "why": why, "prim": prim, "second": second,
            "pre": pre, "total": len(names), "body_extra": extra}


def _fmt_cards(names, limit=3):
    if not names:
        return "无"
    shown = ["[[sources/%s]]" % n for n in names[:limit]]
    if len(names) > limit:
        shown.append("等 %d 篇" % len(names))
    return "、".join(shown)


def note_from_profile(p):
    """纯函数：由证据画像生成注记文字（数字全部来自传入的画像）。

    三种口径**不能混用**（本轮自查发现的措辞错误）：
      ① 登记不全（正文另有 M 篇库内 source 卡未登记）→ 先报「登记不全」，
         因为此时 `evidence_base` 的判定本身**偏低**，说「仅 N 篇一手源」是把元数据缺口
         说成证据缺口（本库头号失真类型的镜像）。
      ② `secondhand`（二手占比 ≥1/3）→ 风险是**转述**，不是单源。若照抄①/③那句，
         会出现「仅 14 篇一手源 … 不得作为领域共识引用」——14 篇一手源并不单薄，
         这句话本身是**假陈述**，比不加注记更有害。
      ③ `single-source` → 用任务书给定句式。
    """
    n_prim = len(p["prim"]) + len(p["pre"])
    n_sec = len(p["second"])
    total = p["total"]
    pct = int(round(100.0 * n_sec / max(1, total)))
    extra = p.get("body_extra") or []
    if extra:
        return ("> 证据强度：本页 `sources:` **登记不全**——已登记 %d 篇（一手 %d / 二手 %d），"
                "但正文另引 %d 篇库内 source 卡未登记（%s）⇒ 本页 `evidence_base=%s` 的判定"
                "**可能偏低**，引用前须先回补登记并逐篇核读，不得据当前标签断言证据薄弱。"
                % (total, n_prim, n_sec, len(extra), _fmt_cards(extra), p["value"]))
    if p["value"] == "secondhand":
        if n_sec == total:
            # 100% 二手时不写「占 100%」：既冗余，又会被 lint 的
            # F2-pct-dense（正文百分数密集）当成一处新数据点（本轮实测多出 1 条 INFO）
            return (NOTE_HEAD + "本页 %d 篇来源**全部**属二手转述（%s），一手源 %d 篇"
                    % (total, _fmt_cards(p["second"]), n_prim)
                    + "——**涉及二手来源支撑的结论须回溯一手文献，不得当作领域共识直接引用**。")
        return (NOTE_HEAD + "本页 %d/%d 篇来源属二手转述（%s，占 %d%%），一手源 %d 篇（%s）"
                "——**涉及二手来源支撑的结论须回溯一手文献，不得当作领域共识直接引用**。"
                % (n_sec, total, _fmt_cards(p["second"]), pct, n_prim,
                   _fmt_cards(p["prim"] + p["pre"])))
    if total == 0:
        return ("> 证据强度：本页 `sources:` **为空**（无任何库内 source 卡）⇒ 全部内容"
                "**无法在库内核验**，不得作为领域共识或一手证据引用。")
    if n_prim == 0:
        return ("> 证据强度：本页目前**没有**可解析的一手源（`sources:` 内 %d 篇均为二手转述：%s），"
                "不得作为领域共识引用。" % (total, _fmt_cards(p["second"])))
    if p["value"] in ("mixed", "strong"):
        # 补登记后不再是单源/二手 ⇒ 不能再说「仅 N 篇一手源」（那是**假陈述**）。
        # 保留一行**当前实际构成**；引用纪律不变：具体数字仍要回卡/回原文核。
        return ("> 证据强度：本页 `sources:` 已登记 %d 篇（一手 %d / 二手 %d），判定 **%s**；"
                "引用具体数字时仍须回对应 source 卡与 raw 原文核对，不得只凭本页转述。"
                % (total, n_prim, n_sec, p["value"]))
    return NOTE_HEAD + "本页结论目前仅 %d 篇一手源（%s）" % (
        n_prim, _fmt_cards(p["prim"] + p["pre"])) + NOTE_TAIL


def derive_note(page, src_pages):
    """生成 `> 证据强度：…` 注记（数字全部现场重算）。

    🔴 两种口径**不能混用**（本轮自查发现的措辞错误）：
      · `single-source`（一手源 ≤1）：用任务书给定句式「仅 N 篇一手源（卡名），不得作为领域共识引用」。
      · `secondhand`（二手占比 ≥1/3）：风险是**转述**，不是单源。若照抄上面那句，
        会出现「仅 14 篇一手源 … 不得作为领域共识引用」——14 篇一手源并不单薄，
        这句话本身是**假陈述**，比不加注记更有害。故改为只陈述二手构成与「回溯一手」的要求。
    """
    return note_from_profile(profile(page, src_pages))


# ---------------------------------------------------------------- 改写（纯函数）
def add_sources(a, add_names):
    """把 `[[sources/x]]` 追加到 frontmatter 的 sources: 块尾（已存在则跳过）。"""
    lines = a.split("\n")
    key = None
    for i, ln in enumerate(lines):
        if re.match(r"^sources\s*:", ln):
            key = i
            break
    if key is None:
        raise ValueError("frontmatter 里没有 sources: 字段，拒绝盲插")
    if not re.match(r"^sources\s*:\s*$", lines[key]):
        raise ValueError("sources: 不是块状列表（内联写法需手工），拒绝改")
    j = key + 1
    items = []
    while j < len(lines) and re.match(r"^\s+-\s", lines[j]):
        items.append(j)
        j += 1
    existing = {QE._resolve_source_name(lines[i].strip().lstrip("- ").strip()) for i in items}
    new_lines = []
    for nm in add_names:
        nm = nm[:-3] if nm.endswith(".md") else nm
        base = nm.split("/")[-1]
        if base in existing:
            continue
        new_lines.append('  - "[[sources/%s.md]]"' % base)
        existing.add(base)
    if not new_lines:
        return a
    insert_at = (items[-1] + 1) if items else key + 1
    lines[insert_at:insert_at] = new_lines
    return "\n".join(lines)


def insert_note(body, note):
    """在 `## 证据状态与判据` 段首插注记；没有该段则建段（放 `## 参见` 之前）。"""
    if note in body:
        return body
    lines = body.split("\n")
    h = None
    for i, ln in enumerate(lines):
        if ln.strip() == EV_HEADING:
            h = i
            break
    if h is not None:
        j = h + 1
        while j < len(lines) and lines[j].strip() == "":
            j += 1
        lines.insert(j, note)
        return "\n".join(lines)
    # 建段：插在 `## 参见` / `## 参考` 之前，否则放末尾
    at = None
    for i, ln in enumerate(lines):
        if ln.strip() in SEE_HEADINGS:
            at = i
            break
    block = [EV_HEADING, "", note, ""]
    if at is None:
        if lines and lines[-1].strip() != "":
            lines.append("")
        lines.extend(block)
        return "\n".join(lines)
    lines[at:at] = block
    return "\n".join(lines)


def apply_decision(page, dec, src_pages):
    """→ (旧文本, 新文本, 说明)。纯函数式：只读盘取原文。"""
    t = read_text(page)
    a, b = split_frontmatter(t)
    if not a:
        raise ValueError("frontmatter 不可解析: %s" % page)
    if dec["action"] == "upgrade":
        a2 = add_sources(a, dec.get("add") or [])
        if a2 == a:
            return t, t, "sources 已含全部目标卡（无改动）"
        new = join_frontmatter(a2.strip("\n"), b)
        if not split_frontmatter(new)[0]:
            raise ValueError("写入后会破坏 frontmatter: %s" % page)
        return t, new, "追加 %d 条 source 卡" % len(dec.get("add") or [])
    if dec["action"] == "downgrade":
        note = derive_note(page, src_pages)
        b2 = insert_note(b, note)
        if b2 == b:
            return t, t, "页内已有同一条注记（无改动）"
        new = join_frontmatter(a.strip("\n"), b2)
        if not split_frontmatter(new)[0]:
            raise ValueError("写入后会破坏 frontmatter: %s" % page)
        return t, new, "插入证据强度注记"
    raise ValueError("未知 action: %r" % dec["action"])


# ---------------------------------------------------------------- 主流程
def load_src():
    return QE.load_source_pages()


def run(plan_path, dry_run=True):
    src_pages = load_src()
    decs = json.load(open(plan_path, encoding="utf-8"))
    if isinstance(decs, dict):
        decs = decs.get("decisions") or []
    known = set()
    for d in glob.glob("wiki/sources/*.md") + glob.glob("projects/*/sources/*.md"):
        known.add(os.path.basename(d)[:-3])
    # 校验：upgrade 目标卡必须存在
    bad = []
    for d in decs:
        for nm in d.get("add") or []:
            base = (nm[:-3] if nm.endswith(".md") else nm).split("/")[-1]
            if base not in known:
                bad.append((d["page"], nm))
    if bad:
        print("❌ 以下 upgrade 目标卡在库内不存在，**拒绝执行**：")
        for p, nm in bad:
            print("   %s : %s" % (p, nm))
        return 2
    print("decisions: %d 条（upgrade %d / downgrade %d）" % (
        len(decs), sum(1 for d in decs if d["action"] == "upgrade"),
        sum(1 for d in decs if d["action"] == "downgrade")))
    today = datetime.date.today().isoformat()
    bak = ".qc_backup_%s" % datetime.date.today().strftime("%Y%m%d")
    n_written = 0
    for d in decs:
        page = d["page"]
        if not os.path.exists(page):
            print("  [!] 页面不存在：%s" % page)
            continue
        old, new, why = apply_decision(page, d, src_pages)
        mark = "[=]" if new == old else "[+]"
        print("%s %s  %s  —— %s" % (mark, page, why, d.get("reason", "")))
        if new == old:
            continue
        if dry_run:
            continue
        dst = os.path.join(bak, page.replace("\\", "/"))
        os.makedirs(os.path.dirname(dst), exist_ok=True)
        shutil.copy2(page, dst)
        ok, detail = write_text_verified(page, new, quiet=False, require_frontmatter=True)
        if not ok:
            print("     [!] 写入失败：%s" % detail)
            continue
        back = read_text(page)
        a2, b2 = split_frontmatter(back)
        if not a2 or parse_frontmatter(a2).get("type") not in ("concept", "topic"):
            print("     [!] 写后复算异常（frontmatter/type）")
            continue
        if d["action"] == "downgrade" and NOTE_HEAD not in b2:
            print("     [!] 写后复算异常（注记未落盘）")
            continue
        n_written += 1
    if dry_run:
        print("\n[干跑] 未写盘。确认后加 --apply。")
        return 0
    print("\n落盘 %d 页（备份 %s/）" % (n_written, bak))
    return 0


def derive_all(out_path):
    """生成「全部 69 页 → 降级」的骨架；主观判断留给调用方改 action。"""
    src_pages = load_src()
    rows = []
    for d in ("wiki/concepts", "wiki/topics"):
        for f in sorted(glob.glob(os.path.join(d, "*.md"))):
            a, _b = split_frontmatter(read_text(f))
            fm = parse_frontmatter(a)
            if fm.get("type") not in ("concept", "topic"):
                continue
            p = profile(f.replace("\\", "/"), src_pages)
            if p["value"] not in ("single-source", "secondhand"):
                continue
            rows.append({"page": f.replace("\\", "/"), "action": "downgrade",
                         "reason": p["why"]})
    with open(out_path, "w", encoding="utf-8") as fh:
        json.dump(rows, fh, ensure_ascii=False, indent=1)
    print("已写 %s（%d 页）" % (out_path, len(rows)))


# ---------------------------------------------------------------- selftest
def run_selftest():
    ok = True
    n = [0]

    def chk(name, cond, extra=""):
        nonlocal ok
        n[0] += 1
        print(("  PASS  " if cond else "  FAIL  ") + name + (("  " + extra) if extra else ""))
        if not cond:
            ok = False

    print("== qc_evidence_note --selftest ==")
    fm = ('type: concept\ntags: [x]\nsummary: "s"\nsources:\n'
          '  - "[[sources/真源A.md]]"\n')
    a2 = add_sources(fm, ["sources/真源B", "sources/真源A"])
    chk("追加新卡（已存在的不重复加）",
        a2.count("真源A") == 1 and '  - "[[sources/真源B.md]]"' in a2, a2.replace("\n", " | "))
    chk("追加落在 sources 块尾（不是文件末尾）",
        a2.index("真源B") < a2.index("summary") + 10**9 and "真源B" in a2.split("summary")[0] + a2.split("summary")[1][:0] + a2)
    chk("重复追加幂等", add_sources(a2, ["sources/真源B"]) == a2)
    try:
        add_sources('type: concept\nsources: ["[[sources/a]]"]\n', ["sources/b"])
        chk("内联 sources 拒绝改", False, "未抛异常")
    except ValueError:
        chk("内联 sources 拒绝改", True)
    try:
        add_sources('type: concept\n', ["sources/b"])
        chk("无 sources 字段拒绝盲插", False, "未抛异常")
    except ValueError:
        chk("无 sources 字段拒绝盲插", True)

    note = "> 证据强度：本页结论目前仅 1 篇一手源（[[sources/真源A]]），不得作为领域共识引用。"
    body = "# T\n\n正文。\n\n## 参见\n\n- [[sources/真源A]]\n"
    b2 = insert_note(body, note)
    chk("无证据段 → 新建在 ## 参见 之前",
        b2.index(EV_HEADING) < b2.index("## 参见") and note in b2)
    chk("幂等：再插一次不变", insert_note(b2, note) == b2)
    body3 = "# T\n\n## 证据状态与判据\n\n- 已有条目\n\n## 参见\n"
    b3 = insert_note(body3, note)
    seg = b3.split(EV_HEADING)[1].split("## 参见")[0]
    chk("已有证据段 → 插在段首（在已有条目之前）",
        seg.index(note) < seg.index("- 已有条目"))
    chk("frontmatter 仍可解析", bool(split_frontmatter(join_frontmatter(a2.strip(), b2))[0]))

    # 注记文字：数字必须来自画像，且措辞须如实
    chk("single-source 注记含篇数/卡名/禁用句",
        "仅 1 篇一手源" in note_from_profile(
            {"value": "single-source", "prim": ["真源A"], "second": [], "pre": [], "total": 1})
        and "[[sources/真源A]]" in note_from_profile(
            {"value": "single-source", "prim": ["真源A"], "second": [], "pre": [], "total": 1})
        and "不得作为领域共识引用" in note_from_profile(
            {"value": "single-source", "prim": ["真源A"], "second": [], "pre": [], "total": 1}))
    # 🔴 回归：secondhand 页即便一手源很多，也不能出现「仅 N 篇一手源…不得作为领域共识」
    #    （本轮自查发现：子方向A 有 14 篇一手源，照抄该句会产出假陈述）
    t2 = note_from_profile({"value": "secondhand", "prim": ["P%d" % i for i in range(14)],
                            "second": ["S%d" % i for i in range(8)], "pre": [], "total": 22})
    chk("secondhand 页（14 篇一手）不得说『仅 14 篇一手源…不得作为领域共识』",
        "仅 14 篇一手源" not in t2 and "属二手转述" in t2 and "回溯一手文献" in t2, t2)
    chk("secondhand 注记含二手占比", "8/22" in t2 and "36%" in t2, t2)
    t3 = note_from_profile({"value": "single-source", "prim": [], "second": ["只有二手"],
                            "pre": [], "total": 1})
    chk("0 篇一手源时不说『仅 0 篇』（措辞如实）", "没有" in t3 and "仅 0 篇" not in t3, t3)
    # ③ 登记不全：正文另有未登记的 source 卡时，先把「元数据缺口」说清楚
    t4 = note_from_profile({"value": "secondhand", "prim": ["P1"], "second": ["S1"],
                            "pre": [], "total": 2, "body_extra": ["E1", "E2", "E3"]})
    chk("正文有未登记卡 → 报『登记不全』而非『仅 N 篇一手源』",
        "登记不全" in t4 and "仅 1 篇一手源" not in t4 and "可能偏低" in t4, t4)
    chk("登记不全注记列出候选卡", "[[sources/E1]]" in t4 and "3 篇" in t4, t4)
    # ④ sources 为空：不能说「0 篇均为二手转述」
    t5 = note_from_profile({"value": "single-source", "prim": [], "second": [],
                            "pre": [], "total": 0})
    chk("sources 为空时措辞如实（不提『二手转述』）",
        "为空" in t5 and "无法在库内核验" in t5 and "二手转述" not in t5, t5)
    # ⑤ 100% 二手时不写「占 100%」（既冗余，又会被 lint F2-pct-dense 计为新数据点）
    t6 = note_from_profile({"value": "secondhand", "prim": [], "second": ["S1"],
                            "pre": [], "total": 1})
    chk("100% 二手时不出现『占 100%』", "全部" in t6 and "100%" not in t6, t6)
    t7 = note_from_profile({"value": "secondhand", "prim": ["P1"], "second": ["S1"],
                            "pre": [], "total": 4})
    chk("非 100% 二手仍保留占比", "占 25%" in t7, t7)
    print("\n%s (%d 项断言)" % ("全部 PASS" if ok else "有 FAIL", n[0]))
    return 0 if ok else 1


NOTE_RE = re.compile(r"^> 证据强度[：:]")


def refresh_notes(pages, src_pages, dry_run=True):
    """重算并**替换**页内已有证据强度注记（sources: 变动后注记会过时）。→ 写页数"""
    from kb_lib import write_text_verified
    n = 0
    for page in pages:
        t = read_text(page)
        a, b = split_frontmatter(t)
        if not a:
            continue
        lines = b.split("\n")
        kept = [ln for ln in lines if not NOTE_RE.match(ln)]
        old = [ln for ln in lines if NOTE_RE.match(ln)]
        note = derive_note(page, src_pages)
        # 去掉旧注记后可能留下连续空行，收敛为单个
        joined = "\n".join(kept)
        joined = re.sub(r"\n{3,}", "\n\n", joined)
        b2 = insert_note(joined, note)
        if b2 == b:
            continue
        new = join_frontmatter(a.strip("\n"), b2)
        if not split_frontmatter(new)[0]:
            print("  [!] %s 改写后 frontmatter 不可解析，跳过" % page)
            continue
        if dry_run:
            print("  [干跑] %s 注记 %d→1 行" % (page, len(old)))
            continue
        ok, detail = write_text_verified(page, new, quiet=True, require_frontmatter=True)
        if not ok:
            print("  [!] %s 写入失败：%s" % (page, detail))
            continue
        n += 1
    return n


def main():
    args = sys.argv[1:]
    if "--help" in args or "-h" in args:
        print(__doc__)
        return 0
    if "--selftest" in args:
        return run_selftest()
    if "--derive" in args:
        i = args.index("--derive")
        out = args[i + 1] if i + 1 < len(args) and not args[i + 1].startswith("-") else \
            "_scratch/round1025/plan_all.json"
        derive_all(out)
        return 0
    if "--refresh" in args:
        src_pages = load_src()
        pages = []
        for d in ("wiki/concepts", "wiki/topics"):
            for f in sorted(glob.glob(os.path.join(d, "*.md"))):
                t = read_text(f)
                if any(NOTE_RE.match(ln) for ln in t.split("\n")):
                    pages.append(f.replace("\\", "/"))
        print("重算注记：%d 页" % len(pages))
        n = refresh_notes(pages, src_pages, dry_run="--apply" not in args)
        print("%s %d 页" % ("已写" if "--apply" in args else "[干跑] 将写", n))
        return 0
    if "--plan" not in args:
        print(__doc__)
        return 2
    plan = args[args.index("--plan") + 1]
    return run(plan, dry_run="--apply" not in args)


if __name__ == "__main__":
    sys.exit(main())
